"""«Школа астрологии» в Telegram-канале (слово владельца 09.11.2026: иногда учить астрологии в деталях: знаки, Солнце, Луна, планеты, Лилит, аспекты).
Один урок раз в 3 дня около 12:30 по часовому поясу бота ($0, нейросеть не нужна), по кругу; это тот самый «один пост в день» от завода (не больше одного).
Честность: исторические и астрономические факты отдельно от астрологической трактовки; в конце каждого урока «язык символов, не наука»."""
LINK = "https://t.me/Numeritabot?start=ad_tg_school"
EVERY_DAYS = 3
FOOT = f'\n\n<i>Это язык астрологии: образы и символы, не наука и не приговор.</i> Свой разбор: <a href="{LINK}">бот Нумериты</a> ✨'
LESSONS = [
    ("Как родились знаки зодиака", "В Вавилоне примерно в V веке до н. э. путь Солнца по небу (эклиптику) разделили на 12 равных частей по 30°: так появился зодиак. Название от греческого «круг животных». 12, потому что в году около 12 лунных месяцев. Важно: знаки это отрезки пути, а созвездия по размеру разные, и из-за медленного сдвига земной оси (прецессии) они давно не совпадают. Астрология работает со знаками как с языком, а не с созвездиями."),
    ("Солнце: кто вы внутри", "Знак Солнца определяет дата рождения. Солнце проходит один знак примерно за 30 дней. В астрологии Солнце это ядро личности: воля, жизненная сила, то, ради чего вы светите. Когда говорят «я Скорпион», имеют в виду именно положение Солнца."),
    ("Луна: чувства и привычки", "Луна обходит все знаки за ~27,3 суток и около 2,5 дня проводит в одном. В астрологии это эмоции, потребность в безопасности, привычки, «как вы успокаиваетесь». Знак Луны меняется быстро, поэтому по дате рождения он может отличаться от знака Солнца. Полный лунный цикл (фазы) длится ~29,5 суток."),
    ("Асцендент: маска первого впечатления", "Асцендент это знак, восходивший над восточным горизонтом в момент и в месте вашего рождения. В астрологии: как вас видят за первые секунды и как вы входите в новое. Он меняется примерно каждые 2 часа, поэтому нужны точное время и город. Приблизительно: на рассвете асцендент совпадает со знаком Солнца, каждые ~2 часа сдвиг на знак вперёд."),
    ("Меркурий: мышление и речь", "Меркурий самая быстрая планета: оборот ~88 суток. В астрологии: ум, речь, переписка, договорённости. «Ретроградный Меркурий» это кажущееся движение назад: с Земли так выглядит, когда мы «обгоняем» планету. Происходит 3–4 раза в год примерно по 3 недели. В астрологии это время переосмысления и перепроверки, а не катастрофа."),
    ("Венера: любовь и ценности", "Венера: ~225 суток на оборот, всегда рядом с Солнцем. В астрологии: любовь, красота, что вы цените и как вы привязываетесь. Знак Венеры показывает ваш «язык любви». Венера бывает ретроградной примерно раз в 18 месяцев: время пересмотреть отношения и ценности."),
    ("Марс: воля и действие", "Марс проходит один знак ~6–7 недель, весь круг за ~2 года. В астрологии: энергия, желания, смелость, спор и злость. Знак Марса показывает, как вы идёте к цели и как защищаете себя."),
    ("Юпитер: рост и смысл", "Юпитер крупнейшая планета, оборот ~12 лет, в знаке около года. В астрологии: расширение, возможности, вера, смысл, щедрость. Куда смотрит Юпитер, там «растёт», но и перебор: в избытке тоже есть урок."),
    ("Сатурн: время, границы, зрелость", "Сатурн делает оборот за ~29,5 лет, в знаке ~2,5 года. В астрологии: ответственность, границы, дисциплина, уроки. «Возвращение Сатурна» около 29–30 лет считают первым взрослым рубежом: время честно спросить, чем вы живёте."),
    ("Уран, Нептун, Плутон: поколения", "Это «дальние» планеты, медленные, они отмечают поколения. Уран (открыт в 1781): перемены и свобода, ~7 лет в знаке, оборот 84 года. Нептун (1846): мечты, вдохновение и иллюзии, ~14 лет в знаке, оборот ~165 лет. Плутон (1930, с 2006 карликовая планета): глубокая трансформация, ~12–31 год в знаке, оборот ~248 лет. Личное значение они получают, когда касаются ваших личных планет."),
    ("Чёрная Луна (Лилит)", "Лилит в астрологии это не планета, а математическая точка: самая дальняя точка лунной орбиты (апогей). В астрологии её связывают с тенью, подавленным, независимостью и «нельзя, но хочется». Её знак показывает, где вы не хотите подстраиваться. Образ связан с мифологической фигурой, но астрологически это про свободу, а не про страшное."),
    ("Аспекты: как планеты «разговаривают»", "Аспект это угол между двумя планетами. Соединение 0°: слияние. Секстиль 60°: возможность. Квадрат 90°: напряжение, которое толкает к действию. Тригон 120°: лёгкость, дар. Оппозиция 180°: два полюса, поиск баланса. Допускается небольшое отклонение (орбис). В астрологии квадрат не «плохой», это двигатель роста."),
    ("Дома: 12 сфер жизни", "Дома делят небо над местом рождения на 12 областей: личность, деньги, общение, дом и семья, творчество, здоровье, партнёрство, глубокие перемены, путешествия и смысл, карьера, друзья, подсознание. Расчёт домов требует времени и города, как и асцендент. Планета в доме показывает, в какой сфере жизни она «играет»."),
    ("Стихии и качества", "Четыре стихии: огонь (Овен, Лев, Стрелец): энергия; земля (Телец, Дева, Козерог): практичность; воздух (Близнецы, Весы, Водолей): идеи и общение; вода (Рак, Скорпион, Рыбы): чувства. Три качества: кардинальные начинают (Овен, Рак, Весы, Козерог), фиксированные держат (Телец, Лев, Скорпион, Водолей), мутабельные меняют (Близнецы, Дева, Стрелец, Рыбы)."),
]


def lesson_html(i: int) -> str:
    title, body = LESSONS[i % len(LESSONS)]
    return f"🌌 <b>Школа астрологии · {i % len(LESSONS) + 1} из {len(LESSONS)}</b>\n<b>{title}</b>\n\n{body}{FOOT}"


async def due(db, now_local) -> str | None:
    """Урок на сейчас или None (окно 12–13 по часовому поясу бота, раз в EVERY_DAYS суток)."""
    from datetime import datetime
    if now_local.hour not in (12, 13):
        return None
    last = await db.kv_get("astroschool:last")
    if last and (now_local.date() - datetime.fromisoformat(last).date()).days < EVERY_DAYS:
        return None
    return lesson_html(int(await db.kv_get("astroschool:n") or 0))


async def mark_sent(db, now_local) -> None:
    n = int(await db.kv_get("astroschool:n") or 0)
    await db.kv_set("astroschool:n", str(n + 1))
    await db.kv_set("astroschool:last", now_local.isoformat())
